"""Publication copy and editable page data for the PHP website."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
pages=[]
def page(slug,title,h1,lead,body,image='',template='content',seo=''):
 pages.append(dict(id=len(pages)+1,slug=slug,title=title,h1=h1,lead=lead,body_html=body,image=image,template=template,seo_title=title+' | Торговая компания «Монополия»',seo_description=seo or lead,active=1,sort_order=len(pages)))
page('home','Кабель, металлопрокат, профнастил и трансформаторы в Санкт-Петербурге','Материалы и оборудование для вашего проекта','Кабельная продукция, металлопрокат, профнастил и трансформаторное оборудование. Подберем позиции по спецификации и подготовим единое коммерческое предложение.', '<p>Торговая компания «Монополия» работает на строительном рынке с 2009 года. Помогаем комплектовать объекты: от кабельной линии и ведомости металла до оборудования электроснабжения.</p>','assets/img/cable.webp','home','Поставки кабеля, металлопроката, профнастила, трансформаторов и КТП в Санкт-Петербурге. Подбор по проекту и расчет стоимости по заявке. Торговая компания «Монополия».')
page('about','О компании','Надежная комплектация начинается с внимания к деталям','Торговая компания «Монополия» поставляет материалы и оборудование для строительства, промышленности и энергетики с 2009 года.', '''<h2>Четыре направления в одной поставке</h2><p>В нашем каталоге представлены кабели и провода, металлопрокат, профилированные листы, силовые трансформаторы и комплектные трансформаторные подстанции. Работаем со спецификациями строительных и производственных предприятий, проектных организаций и частных заказчиков.</p><p>При подборе учитываем назначение продукции, размеры, марку, условия эксплуатации и требования проекта. Если исходных данных недостаточно, менеджер уточнит параметры до подготовки предложения.</p><h2>Как строится сотрудничество</h2><p>Вы направляете список материалов, ведомость или опросный лист. Мы согласуем характеристики, объем, комплектность, стоимость и условия поставки. Затем фиксируем договоренности в коммерческом предложении и документах заказа.</p><p>Сроки, наличие и возможные замены обсуждаются по конкретной заявке. Такой подход помогает связать поставку с графиком работ и избежать ошибок в комплектации.</p><h2>От небольшого заказа до комплексной спецификации</h2><p>Помогаем собрать несколько групп продукции в одном запросе. Заявку можно начать с отдельной позиции каталога, а затем добавить материалы вручную или приложить файл. Для проектного оборудования принимаем технические требования и опросные листы.</p><p>Офис компании находится в Санкт-Петербурге. Условия доставки в другой регион согласуем при расчете заказа.</p>''','assets/img/about.webp',seo='Торговая компания «Монополия»: поставки строительных материалов и электротехнического оборудования с 2009 года. Подбор, комплектация и согласование доставки.')
page('delivery','Условия поставки','Поставка с учетом вашего графика работ','Стоимость, наличие, срок комплектации и способ доставки согласуем по каждой заявке. Все ключевые условия фиксируются до оформления заказа.', '''<h2>Подготовка коммерческого предложения</h2><p>Для расчета укажите наименование и характеристики продукции, количество, адрес доставки и желаемую дату получения. Если есть проектная спецификация, ведомость металла или опросный лист, приложите файл: это ускорит согласование и сократит число уточнений.</p><h2>Оплата и документы</h2><p>Заказ оформляется после согласования состава поставки и коммерческих условий. Порядок оплаты указывается в счете и договоре. Сайт принимает заявки на расчет; онлайн-оплата не предусмотрена.</p><p>Сопроводительные документы определяются видом продукции и согласованными условиями. Паспорта, сертификаты и документы о качестве запрашиваются для выбранного исполнения или партии.</p><h2>Доставка и самовывоз</h2><p>Доставку рассчитываем с учетом региона, габаритов, массы и особенностей разгрузки. Длинномерный прокат, кабельные барабаны и электротехническое оборудование требуют подходящего транспорта и согласования подъезда к объекту.</p><p>Если нужен самовывоз, менеджер подтвердит место и время выдачи, готовность продукции и требования к автомобилю. Офис продаж не является универсальной точкой отгрузки всех товарных групп.</p><h2>Приемка продукции</h2><p>При получении сопоставьте маркировку, количество и комплектность с документами, осмотрите упаковку и продукцию. При обнаружении расхождений зафиксируйте их в документах приемки и свяжитесь с менеджером.</p><h2>Изменения в спецификации</h2><p>Замены, дополнительные позиции и изменения количества согласуются до отгрузки. Для продукции, изготовленной под проект, возможность изменения заказа зависит от стадии производства и условий договора.</p>''','assets/img/delivery.webp',seo='Условия поставки кабеля, металлопроката, профнастила и трансформаторов: расчет заказа, оплата, документы, доставка и самовывоз. Торговая компания «Монополия».')
page('documents','Документы и техническая библиотека','Документы для обоснованного выбора','Подберем сопроводительные документы к выбранной продукции и поможем уточнить требования спецификации. В библиотеке собраны технические материалы из каталога компании.', '''<h2>Документы на поставляемую продукцию</h2><p>Комплект документов зависит от товарной группы, производителя и исполнения. Для запроса укажите марку или модель, требуемый стандарт и объем поставки. Менеджер уточнит возможность предоставления паспорта, сертификата или документа о качестве для конкретной партии.</p><h2>Расчет вместо устаревшего прайс-листа</h2><p>Цена определяется по характеристикам, объему и условиям поставки. Добавьте позиции в заявку или направьте спецификацию на monopoly@list.ru — получите предложение по вашему заказу.</p><h2>Техническая библиотека</h2><p>Ниже доступны архивные справочные документы исходного каталога. Они помогают изучить обозначения и сортамент. Применимость стандарта и действующий комплект документов для заказа подтверждаются при согласовании поставки.</p>''','assets/img/documents.webp','documents')
page('faq','Вопросы и ответы','Ответы на частые вопросы','Как оформить заявку, какие параметры указать и когда согласуются цена и доставка. Если вашего вопроса нет в списке, свяжитесь с менеджером.', '<p>Можно отправить запрос без выбора позиции в каталоге: достаточно описать задачу и приложить имеющиеся материалы. Ответ направим по указанным контактам.</p>','assets/img/documents.webp','faq')
page('contacts','Контакты','Обсудим вашу поставку','Направьте спецификацию или задайте вопрос о продукции. Менеджер уточнит параметры и подготовит коммерческое предложение.', '<p>При посещении офиса заранее свяжитесь с нами, чтобы согласовать встречу. Место отгрузки и условия самовывоза подтверждаются отдельно для выбранной продукции.</p>','assets/img/contacts.webp','contacts','Контакты торговой компании «Монополия»: Санкт-Петербург, Киришская ул., д. 2А. Телефон +7 (812) 932-86-48, электронная почта monopoly@list.ru.')
page('search','Поиск по каталогу','Найдите нужную марку или исполнение','Ищите по наименованию, маркировке или техническим характеристикам. Несколько найденных позиций можно объединить в одну заявку.','<p>Если подходящая позиция не найдена, отправьте ее наименование и параметры через форму заявки. Менеджер уточнит возможность поставки.</p>','','search')
page('request','Корзина и заявка на расчет','Ваша заявка на поставку','Соберите позиции, укажите объем и важные характеристики. Можно добавить товар вручную или приложить готовую спецификацию.','<p>Заявка используется для подготовки коммерческого предложения. Итоговая стоимость, наличие, сроки и условия доставки согласуются с менеджером.</p>','','request')
page('success','Заявка принята','Спасибо, заявка принята','Мы сохранили вашу спецификацию. Менеджер свяжется с вами по указанным контактам для уточнения параметров поставки.','<p>Если требуется дополнить заявку, напишите на monopoly@list.ru и укажите номер обращения. Это поможет связать новые материалы с вашим запросом.</p>','','success')
page('privacy','Политика конфиденциальности','Обработка персональных данных','Торговая компания «Монополия» обрабатывает контактные данные, чтобы отвечать на обращения, рассчитывать поставки и согласовывать заказы.', '''<h2>Какие данные мы получаем</h2><p>При отправке формы вы предоставляете имя, телефон, адрес электронной почты и, по желанию, название организации, город, сообщение и спецификацию. В файлах следует передавать только сведения, необходимые для расчета поставки.</p><h2>Цель и основание обработки</h2><p>Данные используются для ответа на обращение, уточнения технических параметров, подготовки коммерческого предложения и дальнейшего оформления согласованного заказа. Отправка формы сопровождается отдельным подтверждением согласия на обработку данных для этих целей.</p><h2>Хранение и доступ</h2><p>Обращения хранятся в системе учета заявок. Доступ к ним предоставляется сотрудникам, которые обрабатывают запросы. Сообщения могут передаваться через почтовую инфраструктуру для уведомления ответственного сотрудника. Контактные данные не публикуются на сайте и не используются для рекламных рассылок без отдельного согласия.</p><p>Данные сохраняются в течение срока, необходимого для обработки обращения и исполнения заказа, с учетом применимых требований к хранению документов. После отпадения цели обработки данные удаляются или обезличиваются.</p><h2>Файлы cookie и статистика</h2><p>Технические cookie поддерживают сессию, безопасность форм и корзину. Собственная статистика сайта учитывает просмотренные страницы, источник перехода и тип устройства. В статистические отчеты не записываются текст заявки, имя, телефон, email или полный IP-адрес. Сторонние рекламные счетчики не используются.</p><p>Сбор статистики можно отключить кнопкой «Отключить статистику» в нижней части страницы. Технические cookie необходимы для работы корзины и форм.</p><h2>Ваши права и связь с компанией</h2><p>Чтобы уточнить данные, отозвать согласие или запросить удаление сведений, направьте обращение на monopoly@list.ru. Укажите контакт, использованный в заявке, и номер обращения, если он известен. Мы рассмотрим запрос и сообщим о результате.</p><p>Адрес для связи: 195299, Санкт-Петербург, Киришская ул., д. 2А, помещение 8Н. Телефон: +7 (812) 932-86-48.</p>''')
page('information','Техническая информация','Практические материалы по продукции','Обозначения, конструкция, сортамент и применение материалов из каталога. Используйте справочные материалы вместе с требованиями вашего проекта.','<p>Параметры окончательного исполнения подтверждаются технической документацией производителя и согласованной спецификацией. Для подбора направьте марку, размеры и условия эксплуатации.</p>','assets/img/documents.webp','information')
page('calculators','Калькуляторы материалов','Предварительный расчет количества и массы','Оцените теоретическую массу стального проката и площадь профилированных листов. Расчет помогает подготовить заявку; отгрузочные значения уточняются по спецификации.', '''<h2>Как пользоваться расчетом</h2><p>Введите размеры в указанных единицах и количество. Для стальных изделий используется расчетная плотность 7 850 кг/м³. Результат является теоретическим: фактическая масса зависит от допуска размеров и исполнения.</p><h2>Транспортные расходы</h2><p>Стоимость автомобильной или железнодорожной перевозки зависит от маршрута, массы, габаритов и условий выдачи. Для расчета доставки направьте заявку с адресом объекта. На сайте не используются устаревшие тарифные таблицы.</p>''','','calculators')
page('sitemap','Карта сайта','Все разделы сайта','Быстрый переход к товарным направлениям и полезной информации о поставках.','','','sitemap')
page('404','Страница не найдена','Эта страница не найдена','Возможно, адрес изменился. Найдите нужную продукцию в каталоге или отправьте наименование через форму заявки.','','','error')
